(\Pi y:A.B)[x:=u]=
\begin{cases}
\Pi y:A[x:=u].B,&y=x,\\
\Pi y:A[x:=u].B[x:=u],&y\ne x,\ y\notin\operatorname{FV}(u),\\
\Pi z:A[x:=u].(B[y:=z])[x:=u],&y\ne x,\ y\in\operatorname{FV}(u),
\end{cases}

(\lambda y:A.t)[x:=u]=
\begin{cases}
\lambda y:A[x:=u].t,&y=x,\\
\lambda y:A[x:=u].t[x:=u],&y\ne x,\ y\notin\operatorname{FV}(u),\\
\lambda z:A[x:=u].(t[y:=z])[x:=u],&y\ne x,\ y\in\operatorname{FV}(u).
\end{cases}

(\operatorname{let}\ y:=a:A\ \operatorname{in}\ b)[x:=u]=
\begin{cases}
\operatorname{let}\ y:=a[x:=u]:A[x:=u]\ \operatorname{in}\ b,&y=x,\\
\operatorname{let}\ y:=a[x:=u]:A[x:=u]\ \operatorname{in}\ b[x:=u],&y\ne x,\ y\notin\operatorname{FV}(u),\\
\operatorname{let}\ z:=a[x:=u]:A[x:=u]\ \operatorname{in}\ (b[y:=z])[x:=u],&y\ne x,\ y\in\operatorname{FV}(u).
\end{cases}

